scwin.getDuplicateIds = function() {
  const ids = Array.from(document.querySelectorAll("[id]")).map(el => el.id);
  const counts = ids.reduce((m, id) => (m[id] = (m[id] || 0) + 1, m), {});
  return Object.keys(counts).filter(id => counts[id] > 1).length == 0;
}

scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger4').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger5').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger6').click()");
    WebSquare.wUnit.addCommand("pause", "500");	

    WebSquare.wUnit.addCommand("assert", "scwin.getDuplicateIds()", "true");
    WebSquare.wUnit.addCommand("pause", "500");

    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
    var src;
    window.maxNum = 5;
    window.currentNum = 0;
    windowcheck = function(currentNum) {
        if (currentNum == maxNum) {
            windowContainer1.windows[0].window.close();
            return true;
        } else {
            return false;
        }
    };
    createWindow = function(winId, iconUrl, src, title, id, openAction, closeAction) {
        currentNum = windowContainer1.currentWindowNum;
        windowcheck(currentNum);
        //setTimeout( function() {
        windowContainer1.createWindow(winId, iconUrl, src, title, id, openAction, closeAction);
        //}, 100);
    };
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 10-Apr-2018
}
